class Solution:
    def calculate(self, s: str) -> int:
        res = 0; num = 0; sign = 1; st = []
        for ch in s:
            if ch.isdigit(): num = num * 10 + int(ch)
            elif ch in "+-":
                res += sign * num; num = 0; sign = 1 if ch == "+" else -1
            elif ch == "(":
                st.append((res, sign)); res = 0; sign = 1
            elif ch == ")":
                res += sign * num; num = 0; pr, ps = st.pop(); res = pr + ps * res
        return res + sign * num

